def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split by '-' to separate pre-release
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert all-digit identifiers to integers for proper comparison
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
            prerelease_tuple = tuple(parsed_prerelease)
        else:
            prerelease_tuple = None

        return (version_nums, prerelease_tuple)

    def compare_key(item):
        v, original_index = item
        parsed = parse_version(v)
        major_minor_patch = parsed[0]
        prerelease = parsed[1]

        # Version with prerelease sorts before version without prerelease
        # So we use (major_minor_patch, (0, prerelease) if prerelease else (1,))
        if prerelease is None:
            prerelease_key = (1,)
        else:
            prerelease_key = (0, prerelease)

        return (major_minor_patch, prerelease_key, original_index)

    # Add original index to maintain stable sort
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=compare_key)
    return [v for v, _ in sorted_versions]

